(function(G){
  const e=G.escape;
  const button=(action,label,key='',extra='')=>`<button data-git-action="${e(action)}" data-git-key="${e(key)}" ${extra}>${e(label)}</button>`;
  const section=(r,key,label,body,detail='')=>`<section class="git-section">${button('toggle',(r.collapsed.has(key)?'▸ ':'▾ ')+label,key,`class="git-section-title" aria-expanded="${!r.collapsed.has(key)}"`)}${detail?`<span class="git-count">${e(detail)}</span>`:''}${r.collapsed.has(key)?'':`<div class="git-section-body">${body}</div>`}</section>`;
  function files(r,list,source='working'){
    const groups=new Map();for(const f of list){const folder=f.path.includes('/')?f.path.slice(0,f.path.lastIndexOf('/')):'Repository root';if(!groups.has(folder))groups.set(folder,[]);groups.get(folder).push(f)}
    return [...groups].map(([folder,rows])=>{const key=source+':'+folder+':'+(rows[0]?.staged?'staged':'working');return `<div class="git-folder">${button('toggle',(r.collapsed.has(key)?'▸ ':'▾ ')+folder,key,`class="git-folder-title" aria-expanded="${!r.collapsed.has(key)}"`)}${r.collapsed.has(key)?'':rows.map(f=>`<div class="git-file-row"><button class="git-file-name" data-git-action="preview" data-git-key="${e(source+'|'+f.path)}"><span class="git-file-status">${f.status==='untracked'?'U':f.status==='added'?'A':'M'}</span><span>${e(f.path.split('/').at(-1))}</span></button>${source==='working'?button(f.staged?'unstage':'stage',f.staged?'−':'+',f.path,`class="git-file-action" aria-label="${f.staged?'Unstage':'Stage'} ${e(f.path)}"`):''}</div>`).join('')}</div>`}).join('')||'<p class="git-empty">No files.</p>';
  }
  function field(name,label,value,placeholder){return `<label class="git-field">${e(label)}<input data-git-field="${name}" value="${e(value)}" placeholder="${e(placeholder)}" autocomplete="off"></label>`}
  G.render=function(workspace){
    const r=G.repository(workspace),sync=G.counts(r),staged=r.files.filter(f=>f.staged),unstaged=r.files.filter(f=>!f.staged&&f.status!=='untracked'),untracked=r.files.filter(f=>!f.staged&&f.status==='untracked');
    const head=`<div class="git-repository"><h2>${e(workspace)}</h2><span>Sample repository</span></div>`;
    if(!r.initialized)return head+'<p class="git-empty">This workspace has no Git repository.</p>'+button('initialize','Initialize sample repository');
    if(r.confirm)return head+`<div class="git-confirm" role="alertdialog" aria-labelledby="git-confirm-title"><h3 id="git-confirm-title">${e(r.confirm.title)}</h3><p>${e(r.confirm.detail)}</p><div class="git-actions">${button('cancel','Cancel')}${button('confirm',r.confirm.label,'','class="git-danger"')}</div></div>`;
    if(r.preview){const f=r.preview;return head+button('back','‹ Git tree')+`<div class="git-diff-head"><h3>${e(f.path)}</h3><p>${f.source==='working'?'Working changes':'Saved change'} · full-file comparison</p></div><div class="git-diff"><h4>Before</h4><pre>${e(f.before||'(empty file)')}</pre><h4>After</h4><pre>${e(f.after||'(empty file)')}</pre></div>${f.source==='working'?`<div class="git-actions">${button(f.staged?'unstage':'stage',f.staged?'Unstage':'Stage',f.path)}${button('discard','Discard changes',f.path,'class="git-danger-text"')}</div>`:''}`}
    const changes=section(r,'staged','Staged',files(r,staged),staged.length)+section(r,'unstaged','Unstaged',files(r,unstaged),unstaged.length)+section(r,'untracked','Untracked',files(r,untracked),untracked.length);
    const branches=`<p class="git-subtitle">Local branches</p>${Object.entries(r.branches).map(([name,b])=>`<div class="git-branch-row">${button('switch',(name===r.branch?'✓ ':'')+name,name,`class="git-branch-name" ${name===r.branch?'aria-current="true"':''}`)}${name!==r.branch?button('delete-branch','Delete',name,'class="git-small-action"'):''}</div>`).join('')}${field('branchName','New branch',r.branchName,'feature/name')}${button('create-branch','Create branch')}<p class="git-subtitle">Remote branches</p>${Object.keys(r.remoteRefs).map(ref=>button('checkout-remote',ref,ref,'class="git-wide-action"')).join('')||'<p class="git-empty">No remote branches.</p>'}`;
    const history=G.history(r).map(c=>section(r,'commit:'+c.id,c.message,`<p class="git-meta">${e(c.id)} · ${e(c.when)}</p>${files(r,c.files,c.id)}`)).join('')||'<p class="git-empty">No commits yet.</p>';
    const stashes=field('stashName','Stash name',r.stashName,'Work in progress')+button('stash','Stash changes','',''+(!r.files.length?'disabled':''))+r.stashes.map(s=>section(r,s.id,s.name,`<p class="git-meta">From ${e(s.branch)}</p>${files(r,s.files,'stash:'+s.id)}<div class="git-actions">${button('apply-stash','Apply',s.id)}${button('drop-stash','Drop',s.id,'class="git-danger-text"')}</div>`)).join('');
    const remotes=Object.entries(r.remotes).map(([name,remote])=>`<div class="git-remote"><strong>${e(name)}</strong><p>${e(remote.url)}</p></div>`).join('')||button('add-remote','Add sample origin');
    return head+`<div class="git-branch-status"><strong>⑂ ${e(r.branch)}</strong><span>${sync.tracking?`${sync.ahead} ahead · ${sync.behind} behind`:'No upstream'}</span></div><div class="git-actions git-sync">${button('fetch','Fetch')}${button('pull','Pull')}${button('push',sync.tracking?'Push':'Publish')}</div>${r.notice?`<p class="git-notice" role="status">${e(r.notice)}</p>`:''}<div class="git-actions">${button('stage-all','Stage all','',''+(!r.files.some(f=>!f.staged)?'disabled':''))}${button('unstage-all','Unstage all','',''+(!staged.length?'disabled':''))}</div><div class="git-tree">${changes}</div><div class="git-commit">${field('commitMessage','Commit message',r.commitMessage,'Describe the staged changes')}${button('commit',`Commit ${staged.length} staged file${staged.length===1?'':'s'}`,'',!staged.length?'disabled':'')}</div>${section(r,'branches','Branches',branches)}${section(r,'history','History',history,G.history(r).length)}${section(r,'remotes','Remotes',remotes)}${section(r,'stashes','Stashes',stashes,r.stashes.length)}`;
  };
})(GitPrototype);
